def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != bg and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append(comp)

    if not comps:
        return [row[:] for row in grid]

    source = max(comps, key=len)
    r0 = min(r for r, c in source)
    r1 = max(r for r, c in source)
    c0 = min(c for r, c in source)
    c1 = max(c for r, c in source)
    pattern = [(r-r0, c-c0, grid[r][c]) for r, c in source]
    center_r, center_c = (r1-r0)//2, (c1-c0)//2

    out = [row[:] for row in grid]
    for comp in comps:
        if comp is source:
            continue
        # The remaining components are the point markers.
        for r, c in comp:
            out[r][c] = bg
            top_r, left_c = r-center_r, c-center_c
            for dr, dc, color in pattern:
                nr, nc = top_r+dr, left_c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = color

    return out
